// ServicoPedido.java — em producao desde 2023.
package com.empresa.pedidos;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

public class ServicoPedido {

    private final RepositorioPedidos repositorio;
    private final CalculadoraFrete frete;
    private final Notificador notificador;

    public ServicoPedido(RepositorioPedidos repositorio, CalculadoraFrete frete, Notificador notificador) {
        this.repositorio = repositorio;
        this.frete = frete;
        this.notificador = notificador;
    }

    public Pedido abrir(Carrinho carrinho, Cliente cliente) {
        if (carrinho.itens().isEmpty()) {
            throw new PedidoInvalido("carrinho vazio");
        }

        Pedido pedido = new Pedido(cliente.id(), carrinho.itens());
        pedido.setValorFrete(frete.calcular(carrinho, cliente.endereco()));
        pedido.setTotal(totalCom(carrinho, cliente));

        repositorio.salvar(pedido);
        notificador.pedidoAberto(pedido);
        return pedido;
    }

    private long totalCom(Carrinho carrinho, Cliente cliente) {
        long subtotal = 0;
        for (Item item : carrinho.itens()) {
            subtotal += item.precoCentavos() * item.quantidade();
        }

        long desconto = descontoDe(subtotal, cliente);
        long freteCentavos = frete.calcular(carrinho, cliente.endereco());

        return Math.max(0, subtotal - desconto) + freteCentavos;
    }

    private long descontoDe(long subtotal, Cliente cliente) {
        long desconto = 0;

        if (cliente.primeiraCompra()) {
            desconto += subtotal / 10;
        }
        if (cliente.totalDePedidos() > 10) {
            desconto += subtotal * 5 / 100;
        }

        // Acumulam, mas com teto: o limite vale sobre a soma, nao por regra.
        long teto = subtotal * 15 / 100;
        return Math.min(desconto, teto);
    }

    public List<Pedido> pendentesDoCliente(String clienteId) {
        List<Pedido> todos = repositorio.listarPorStatus("pending", 100);
        List<Pedido> meus = new ArrayList<>();
        for (Pedido pedido : todos) {
            if (pedido.clienteId().equals(clienteId)) {
                meus.add(pedido);
            }
        }
        return meus;
    }

    public Optional<Pedido> porId(String id) {
        return repositorio.buscar(id);
    }
}

